import json
import pandas as pd

SOURCES = ["source_a", "source_b", "source_c"]
FIELDS = ["name", "email", "created_date", "status"]

FIELD_MAP_A = {"id": "user_id", "full_name": "name", "email": "email",
               "registration_date": "created_date", "status": "status"}
FIELD_MAP_B = {"user_id": "user_id", "name": "name", "email_address": "email",
               "created_at": "created_date"}
FIELD_MAP_C = {"userId": "user_id", "userName": "name", "email": "email",
               "joined": "created_date"}


def load_source_a():
    with open("/data/source_a/users.json") as f:
        rows = json.load(f)
    return [{FIELD_MAP_A[k]: v for k, v in r.items() if k in FIELD_MAP_A} for r in rows]


def load_source_b():
    df = pd.read_csv("/data/source_b/users.csv")
    out = []
    for _, r in df.iterrows():
        rec = {FIELD_MAP_B[k]: r[k] for k in df.columns if k in FIELD_MAP_B}
        out.append(rec)
    return out


def load_source_c():
    df = pd.read_parquet("/data/source_c/users.parquet")
    out = []
    for _, r in df.iterrows():
        rec = {FIELD_MAP_C[k]: r[k] for k in df.columns if k in FIELD_MAP_C}
        out.append(rec)
    return out


def normalize_date(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    return pd.to_datetime(v).strftime("%Y-%m-%d")


def normalize_record(rec):
    out = {"user_id": int(rec["user_id"])}
    for f in FIELDS:
        if f in rec and rec[f] is not None and not (isinstance(rec[f], float) and pd.isna(rec[f])):
            if f == "created_date":
                out[f] = normalize_date(rec[f])
            else:
                out[f] = str(rec[f])
    return out


def main():
    by_source = {
        "source_a": [normalize_record(r) for r in load_source_a()],
        "source_b": [normalize_record(r) for r in load_source_b()],
        "source_c": [normalize_record(r) for r in load_source_c()],
    }

    indexed = {s: {r["user_id"]: r for r in recs} for s, recs in by_source.items()}

    all_ids = sorted(set().union(*[set(idx.keys()) for idx in indexed.values()]))

    merged_rows = []
    conflicts = []

    for uid in all_ids:
        merged = {"user_id": uid}
        for field in FIELDS:
            values = {}
            for s in SOURCES:
                if uid in indexed[s] and field in indexed[s][uid]:
                    values[s] = indexed[s][uid][field]

            if not values:
                continue

            selected = None
            for s in SOURCES:
                if s in values:
                    selected = values[s]
                    break
            merged[field] = selected

            distinct = set(values.values())
            if len(distinct) > 1:
                conflicts.append({
                    "user_id": uid,
                    "field": field,
                    "values": values,
                    "selected": selected,
                })

        merged_rows.append(merged)

    df = pd.DataFrame(merged_rows)
    df["user_id"] = df["user_id"].astype("int64")
    for col in ["name", "email", "created_date", "status"]:
        if col not in df.columns:
            df[col] = None
        df[col] = df[col].astype("object")
    df = df[["user_id", "name", "email", "created_date", "status"]]
    df.to_parquet("/app/merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w") as f:
        json.dump(report, f, indent=2)

    print(df)
    print(f"Conflicts: {len(conflicts)}")


if __name__ == "__main__":
    main()

